import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../../core/theme/tokens.dart';
import '../../core/theme/typography.dart';

/// Passport-stamp style chip — slight rotation, dashed border, ink color.
class StampChip extends StatelessWidget {
  const StampChip({super.key, required this.label, this.color, this.angle = -0.04});
  final String label;
  final Color? color;
  final double angle;

  @override
  Widget build(BuildContext context) {
    final c = color ?? AppColors.stamp;
    return Transform.rotate(
      angle: angle,
      child: CustomPaint(
        painter: _DashedBorderPainter(color: c.withValues(alpha: 0.7)),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
          child: Text(
            label.toUpperCase(),
            style: AppType.eyebrow(color: c).copyWith(letterSpacing: 1.8, fontWeight: FontWeight.w700),
          ),
        ),
      ),
    );
  }
}

class _DashedBorderPainter extends CustomPainter {
  _DashedBorderPainter({required this.color});
  final Color color;
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.4;
    const dashW = 4.0, dashGap = 3.0;
    final rect = RRect.fromRectAndRadius(
      Rect.fromLTWH(0, 0, size.width, size.height),
      const Radius.circular(4),
    );
    final path = Path()..addRRect(rect);
    final metrics = path.computeMetrics();
    for (final m in metrics) {
      double dist = 0;
      while (dist < m.length) {
        final next = math.min(dist + dashW, m.length);
        canvas.drawPath(m.extractPath(dist, next), paint);
        dist = next + dashGap;
      }
    }
  }

  @override
  bool shouldRepaint(covariant _DashedBorderPainter old) => old.color != color;
}

import 'package:flutter/material.dart';
import '../../core/theme/tokens.dart';

/// A boarding-pass shaped card with a perforated notch on each side.
class BoardingCard extends StatelessWidget {
  const BoardingCard({
    super.key,
    required this.child,
    this.color,
    this.onTap,
    this.padding = const EdgeInsets.all(AppSpacing.x5),
    this.notchPosition = 0.62,
    this.elevation = AppShadows.card,
  });

  final Widget child;
  final Color? color;
  final VoidCallback? onTap;
  final EdgeInsetsGeometry padding;
  final double notchPosition;
  final List<BoxShadow> elevation;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: PhysicalShape(
        clipper: _BoardingClipper(notch: notchPosition),
        color: color ?? AppColors.parchmentSoft,
        elevation: 0,
        child: Container(
          decoration: BoxDecoration(boxShadow: elevation),
          child: ClipPath(
            clipper: _BoardingClipper(notch: notchPosition),
            child: Padding(padding: padding, child: child),
          ),
        ),
      ),
    );
  }
}

class _BoardingClipper extends CustomClipper<Path> {
  _BoardingClipper({required this.notch});
  final double notch;

  @override
  Path getClip(Size size) {
    const r = AppRadius.lg;
    const notchR = 10.0;
    final ny = size.height * notch;
    final p = Path();
    p.moveTo(r, 0);
    p.lineTo(size.width - r, 0);
    p.quadraticBezierTo(size.width, 0, size.width, r);
    p.lineTo(size.width, ny - notchR);
    p.arcToPoint(Offset(size.width, ny + notchR),
        radius: const Radius.circular(notchR), clockwise: false);
    p.lineTo(size.width, size.height - r);
    p.quadraticBezierTo(size.width, size.height, size.width - r, size.height);
    p.lineTo(r, size.height);
    p.quadraticBezierTo(0, size.height, 0, size.height - r);
    p.lineTo(0, ny + notchR);
    p.arcToPoint(Offset(0, ny - notchR),
        radius: const Radius.circular(notchR), clockwise: false);
    p.lineTo(0, r);
    p.quadraticBezierTo(0, 0, r, 0);
    p.close();
    return p;
  }

  @override
  bool shouldReclip(covariant _BoardingClipper old) => old.notch != notch;
}

/// A horizontal dashed divider — for boarding pass perforation lines.
class DashedDivider extends StatelessWidget {
  const DashedDivider({super.key, this.color, this.height = 1, this.dash = 4, this.gap = 4});
  final Color? color;
  final double height;
  final double dash;
  final double gap;

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: height,
      child: LayoutBuilder(builder: (ctx, c) {
        final count = (c.maxWidth / (dash + gap)).floor();
        return Row(
          children: List.generate(
            count,
            (_) => Padding(
              padding: EdgeInsets.only(right: gap),
              child: Container(
                width: dash,
                height: height,
                color: color ?? AppColors.hairline,
              ),
            ),
          ),
        );
      }),
    );
  }
}

import 'package:flutter/material.dart';
import '../../core/theme/tokens.dart';
import '../../core/theme/typography.dart';

class PrimaryButton extends StatefulWidget {
  const PrimaryButton({
    super.key,
    required this.label,
    this.onTap,
    this.icon,
    this.expand = false,
    this.color,
    this.fg,
  });

  final String label;
  final VoidCallback? onTap;
  final IconData? icon;
  final bool expand;
  final Color? color;
  final Color? fg;

  @override
  State<PrimaryButton> createState() => _PrimaryButtonState();
}

class _PrimaryButtonState extends State<PrimaryButton> {
  bool _down = false;

  @override
  Widget build(BuildContext context) {
    final bg = widget.color ?? AppColors.ink;
    final fg = widget.fg ?? AppColors.parchmentSoft;
    return GestureDetector(
      onTapDown: (_) => setState(() => _down = true),
      onTapUp: (_) => setState(() => _down = false),
      onTapCancel: () => setState(() => _down = false),
      onTap: widget.onTap,
      child: AnimatedContainer(
        duration: AppDurations.fast,
        curve: kAppCurve,
        transform: Matrix4.identity()..scale(_down ? 0.98 : 1.0),
        transformAlignment: Alignment.center,
        padding: const EdgeInsets.symmetric(horizontal: 28, vertical: 18),
        decoration: BoxDecoration(
          color: bg,
          borderRadius: BorderRadius.circular(AppRadius.pill),
          boxShadow: _down ? [] : AppShadows.card,
        ),
        child: Row(
          mainAxisSize: widget.expand ? MainAxisSize.max : MainAxisSize.min,
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(widget.label, style: AppType.body(15, color: fg, w: FontWeight.w600)),
            if (widget.icon != null) ...[
              const SizedBox(width: 12),
              Icon(widget.icon, color: fg, size: 18),
            ],
          ],
        ),
      ),
    );
  }
}

class GhostButton extends StatelessWidget {
  const GhostButton({super.key, required this.label, this.onTap, this.icon});
  final String label;
  final VoidCallback? onTap;
  final IconData? icon;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 16),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(AppRadius.pill),
          border: Border.all(color: AppColors.hairline, width: 1.4),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(label, style: AppType.body(14, w: FontWeight.w600)),
            if (icon != null) ...[
              const SizedBox(width: 10),
              Icon(icon, size: 16, color: AppColors.ink),
            ],
          ],
        ),
      ),
    );
  }
}

import 'package:country_flags/country_flags.dart';
import 'package:flutter/material.dart';
import '../../core/theme/tokens.dart';
import '../../core/theme/typography.dart';

class CountryPill extends StatelessWidget {
  const CountryPill({super.key, required this.code, required this.label, this.dense = false});
  final String code; // 'DZ' or 'FR'
  final String label;
  final bool dense;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: EdgeInsets.symmetric(
        horizontal: dense ? 10 : 14,
        vertical: dense ? 6 : 9,
      ),
      decoration: BoxDecoration(
        color: AppColors.parchmentSoft,
        borderRadius: BorderRadius.circular(AppRadius.pill),
        border: Border.all(color: AppColors.hairline, width: 1),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          ClipRRect(
            borderRadius: BorderRadius.circular(2),
            child: CountryFlag.fromCountryCode(code, height: dense ? 12 : 14, width: dense ? 18 : 22),
          ),
          SizedBox(width: dense ? 6 : 8),
          Text(label,
              style: AppType.mono(dense ? 11 : 12.5, w: FontWeight.w600)
                  .copyWith(letterSpacing: 0.8)),
        ],
      ),
    );
  }
}

