            color: AppColors.parchmentSoft,
            borderRadius: BorderRadius.circular(AppRadius.lg),
            border: Border.all(color: AppColors.hairline),
          ),
          child: Column(
            children: [
              _CountrySelectRow(
                label: "FROM",
                code: _from,
                onTap: () => setState(() {
                  final tmp = _from;
                  _from = _to;
                  _to = tmp;
                }),
              ),
              const SizedBox(height: 8),
              Row(
                children: [
                  Expanded(child: Container(height: 1, color: AppColors.hairline)),
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 8),
                    child: GestureDetector(
                      onTap: () => setState(() {
                        final tmp = _from;
                        _from = _to;
                        _to = tmp;
                      }),
                      child: Container(
                        width: 32,
                        height: 32,
                        decoration: BoxDecoration(
                          color: AppColors.ink,
                          borderRadius: BorderRadius.circular(AppRadius.pill),
                        ),
                        child: const Icon(Icons.swap_vert_rounded,
                            color: AppColors.parchment, size: 18),
                      ),
                    ),
                  ),
                  Expanded(child: Container(height: 1, color: AppColors.hairline)),
                ],
              ),
              const SizedBox(height: 8),
              _CountrySelectRow(
                label: "TO",
                code: _to,
                onTap: () => setState(() {
                  final tmp = _from;
                  _from = _to;
                  _to = tmp;
                }),
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _whenBlock() {
    final options = ["Today", "This week", "Next week", "Custom"];
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text("When", style: AppType.eyebrow()),
        const SizedBox(height: AppSpacing.x3),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: options
              .map((o) => _Choice(label: o, selected: _when == o, onTap: () => setState(() => _when = o)))
              .toList(),
        ),
      ],
    );
  }

  Widget _typeBlock() {
    final options = ["Documents", "Small box", "Electronics", "Clothing", "Food"];
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
