import 'package:country_flags/country_flags.dart';
import 'package:country_flags/src/flag_emoji.dart';
import 'package:country_flags/src/flag_image.dart';
import 'package:flutter/material.dart';

/// {@template shape}
/// The shape of the flag.
/// {@endtemplate}
sealed class Shape {
  const Shape();
}

/// {@template rectangle}
/// Rectangular shape.
/// {@endtemplate}
class Rectangle extends Shape {
  /// {@macro rectangle}
  const Rectangle();
}

/// {@template circle}
/// Circular shape.
/// {@endtemplate}
class Circle extends Shape {
  /// {@macro circle}
  const Circle();
}

/// {@template rounded_rectangle}
/// Rectangular shape with rounded corners.
/// {@endtemplate}
class RoundedRectangle extends Shape {
  /// {@macro rounded_rectangle}
  const RoundedRectangle(this.borderRadius);

  /// The border radius of the corners of the rectangle.
  final double borderRadius;

  /// Creates a copy of this [RoundedRectangle] but with the given fields
  /// replaced by new values.
  RoundedRectangle copyWith({
    double? borderRadius,
  }) {
    return RoundedRectangle(
      borderRadius ?? this.borderRadius,
    );
  }
}

