import 'package:flutter/material.dart';

/// ShipTrip design tokens — "Mediterranean transit" aesthetic.
/// Algerian heritage emerald, Saharan ochre, parchment, gold.
class AppColors {
  AppColors._();

  static const parchment = Color(0xFFF4EFE6);
  static const parchmentDeep = Color(0xFFEAE3D2);
  static const parchmentSoft = Color(0xFFFAF6EE);

  static const ink = Color(0xFF0E1F2C);
  static const inkSoft = Color(0xFF2A3B49);
  static const inkMute = Color(0xFF6B7785);

  static const emerald = Color(0xFF0E5A4F);
  static const emeraldDeep = Color(0xFF073C34);
  static const emeraldGlow = Color(0xFF2A8475);

  static const terracotta = Color(0xFFE8763A);
  static const terracottaDeep = Color(0xFFC75E26);

  static const gold = Color(0xFFC9A961);
  static const goldDeep = Color(0xFFA88842);

  /// Signature accent used for the bottom nav and key CTAs.
  static const sun = Color(0xFFFBBC04);
  static const sunDeep = Color(0xFFD89E00);

  static const success = Color(0xFF2A8475);
  static const danger = Color(0xFFB23A2E);
  static const warning = Color(0xFFE8A33A);

  static const stamp = Color(0xFFB23A2E);

  static const hairline = Color(0x1A0E1F2C);
  static const hairlineSoft = Color(0x0D0E1F2C);
}

class AppRadius {
  AppRadius._();
  static const xs = 6.0;
  static const sm = 10.0;
  static const md = 16.0;
  static const lg = 24.0;
  static const xl = 32.0;
  static const pill = 999.0;
}

class AppSpacing {
  AppSpacing._();
  static const x1 = 4.0;
  static const x2 = 8.0;
  static const x3 = 12.0;
  static const x4 = 16.0;
  static const x5 = 20.0;
  static const x6 = 24.0;
  static const x8 = 32.0;
  static const x10 = 40.0;
  static const x12 = 48.0;
  static const x16 = 64.0;
  static const x20 = 80.0;
}

class AppShadows {
  AppShadows._();

  static const card = [
    BoxShadow(
      color: Color(0x0F0E1F2C),
      blurRadius: 24,
      offset: Offset(0, 8),
    ),
    BoxShadow(
      color: Color(0x080E1F2C),
      blurRadius: 4,
      offset: Offset(0, 2),
    ),
  ];

  static const elevated = [
    BoxShadow(
      color: Color(0x1A0E1F2C),
      blurRadius: 40,
      offset: Offset(0, 16),
    ),
    BoxShadow(
      color: Color(0x0F0E1F2C),
      blurRadius: 8,
      offset: Offset(0, 4),
    ),
  ];

  static const stamped = [
    BoxShadow(
      color: Color(0x14B23A2E),
      blurRadius: 0,
      offset: Offset(2, 2),
    ),
  ];
}

class AppDurations {
  AppDurations._();
  static const fast = Duration(milliseconds: 180);
  static const med = Duration(milliseconds: 320);
  static const slow = Duration(milliseconds: 540);
  static const epic = Duration(milliseconds: 900);
}

const kAppCurve = Cubic(0.16, 1, 0.3, 1); // expressive ease-out

import 'package:flutter/material.dart';
import '../../core/theme/tokens.dart';
import '../../core/theme/typography.dart';

class AppInput extends StatelessWidget {
  const AppInput({
    super.key,
    required this.controller,
    required this.hint,
    this.label,
    this.icon,
    this.obscure = false,
    this.suffix,
    this.keyboardType,
    this.onChanged,
    this.autofocus = false,
  });

  final TextEditingController controller;
  final String hint;
  final String? label;
  final IconData? icon;
  final bool obscure;
  final Widget? suffix;
  final TextInputType? keyboardType;
  final ValueChanged<String>? onChanged;
  final bool autofocus;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (label != null) ...[
          Text(label!.toUpperCase(), style: AppType.eyebrow()),
          const SizedBox(height: 8),
        ],
        TextField(
          controller: controller,
          obscureText: obscure,
          keyboardType: keyboardType,
          autofocus: autofocus,
          onChanged: onChanged,
          style: AppType.body(15, w: FontWeight.w500),
          decoration: InputDecoration(
            hintText: hint,
            hintStyle: AppType.body(14, color: AppColors.inkMute),
            prefixIcon: icon == null
                ? null
                : Padding(
                    padding: const EdgeInsets.only(left: 14, right: 8),
                    child: Icon(icon, size: 18, color: AppColors.inkMute),
                  ),
            prefixIconConstraints: const BoxConstraints(minWidth: 0),
            suffixIcon: suffix,
            filled: true,
            fillColor: AppColors.parchmentSoft,
            contentPadding:
                const EdgeInsets.symmetric(horizontal: 14, vertical: 16),
            enabledBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(AppRadius.md),
              borderSide: const BorderSide(color: AppColors.hairline, width: 1.2),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(AppRadius.md),
              borderSide: const BorderSide(color: AppColors.ink, width: 1.4),
            ),
          ),
        ),
      ],
    );
  }
}

/// Big tappable + / - stepper used for weight, kg, count.
class NumberStepper extends StatelessWidget {
  const NumberStepper({
    super.key,
    required this.value,
    required this.onChanged,
    this.min = 1,
    this.max = 25,
    this.unit = "kg",
    this.step = 1,
  });

  final int value;
  final ValueChanged<int> onChanged;
  final int min;
  final int max;
  final String unit;
  final int step;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
      decoration: BoxDecoration(
        color: AppColors.parchmentSoft,
        borderRadius: BorderRadius.circular(AppRadius.pill),
        border: Border.all(color: AppColors.hairline, width: 1.2),
      ),
      child: Row(
        children: [
          _btn(
            icon: Icons.remove_rounded,
            onTap: value > min ? () => onChanged(value - step) : null,
          ),
          Expanded(
            child: Center(
              child: Row(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.baseline,
                textBaseline: TextBaseline.alphabetic,
                children: [
                  Text("$value",
                      style: AppType.display(28, w: FontWeight.w500)),
                  const SizedBox(width: 6),
                  Text(unit,
                      style:
                          AppType.mono(13, color: AppColors.inkMute, w: FontWeight.w600)),
                ],
              ),
            ),
          ),
          _btn(
            icon: Icons.add_rounded,
            onTap: value < max ? () => onChanged(value + step) : null,
          ),
        ],
      ),
    );
  }

  Widget _btn({required IconData icon, VoidCallback? onTap}) {
    final disabled = onTap == null;
    return GestureDetector(
      onTap: onTap,
      child: AnimatedContainer(
        duration: AppDurations.fast,
        width: 44,
        height: 44,
        decoration: BoxDecoration(
          color: disabled ? AppColors.parchmentDeep : AppColors.ink,
          shape: BoxShape.circle,
        ),
        child: Icon(
          icon,
          color: disabled ? AppColors.inkMute : AppColors.parchment,
          size: 20,
        ),
      ),
    );
  }
}

