  final String flightNo;
  final String origin;
  final String dest;
  final String originCode;
  final String destCode;

  @override
  State<FlightTrackingScreen> createState() => _FlightTrackingScreenState();
}

class _FlightTrackingScreenState extends State<FlightTrackingScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _ctl;

  @override
  void initState() {
    super.initState();
    _ctl = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 18),
    )..repeat();
  }

  @override
  void dispose() {
    _ctl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.ink,
      body: Stack(
        children: [
          // Stylized map background
          Positioned.fill(
            child: AnimatedBuilder(
              animation: _ctl,
              builder: (_, __) => CustomPaint(
                painter: _MapPainter(progress: _ctl.value),
              ),
            ),
          ),
          // Top + bottom UI
          SafeArea(
            child: Column(
              children: [
                _topBar(),
                const Spacer(),
                _bottomSheet(),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _topBar() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(
          AppSpacing.x4, AppSpacing.x4, AppSpacing.x4, 0),
      child: Row(
        children: [
          IconButton(
            onPressed: () => context.pop(),
            icon: const Icon(Icons.arrow_back_rounded,
                color: AppColors.parchment),
            style: IconButton.styleFrom(
              backgroundColor: AppColors.inkSoft.withValues(alpha: 0.7),
              shape: const CircleBorder(),
            ),
          ),
          const Spacer(),
          StampChip(label: "IN TRANSIT", color: AppColors.sun),
        ],
      ),
    );
  }

  Widget _bottomSheet() {
    return AnimatedBuilder(
      animation: _ctl,
      builder: (_, __) {
        final p = _ctl.value;
        final altitude = 9800 + (math.sin(p * math.pi) * 600).round();
        final speed = 845 + (math.sin(p * math.pi * 2) * 12).round();
        final etaMin = ((1 - p) * 138).round();
        final h = etaMin ~/ 60;
        final m = etaMin % 60;
        return Container(
          decoration: const BoxDecoration(
            color: AppColors.parchment,
            borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
          ),
          padding: const EdgeInsets.fromLTRB(
              AppSpacing.x6, AppSpacing.x5, AppSpacing.x6, AppSpacing.x6),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Center(
                child: Container(
                  width: 40,
                  height: 4,
                  decoration: BoxDecoration(
                    color: AppColors.hairline,
                    borderRadius: BorderRadius.circular(2),
                  ),
                ),
              ),
              const SizedBox(height: AppSpacing.x4),
              Row(
                children: [
                  Text(widget.flightNo,
                      style: AppType.mono(13, w: FontWeight.w700)),
                  const SizedBox(width: 8),
                  Container(
                      width: 3, height: 3, color: AppColors.inkMute),
                  const SizedBox(width: 8),
                  Text("Air Algérie · A330",
                      style: AppType.body(12,
                          color: AppColors.inkMute, w: FontWeight.w500)),
                ],
              ),
              const SizedBox(height: 8),
              Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(widget.originCode,
                          style: AppType.display(34,
                              w: FontWeight.w400, height: 1)),
                      Text(widget.origin,
                          style: AppType.body(12,
                              color: AppColors.inkMute, w: FontWeight.w500)),
                      Text("Departed 09:42",
                          style: AppType.mono(10.5,
                              color: AppColors.emerald, w: FontWeight.w600)),
                    ],
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Column(
                      children: [
                        const SizedBox(height: 14),
                        SizedBox(
                          height: 18,
                          child: CustomPaint(
                            painter: _ProgressLinePainter(progress: p),
                            size: Size.infinite,
                          ),
                        ),
                        const SizedBox(height: 6),
                        Text("${(p * 100).toInt()}%",
                            style: AppType.mono(11.5,
                                color: AppColors.inkMute,
                                w: FontWeight.w700)),
                      ],
                    ),
                  ),
                  const SizedBox(width: 14),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.end,
                    children: [
                      Text(widget.destCode,
                          style: AppType.display(34,
                              w: FontWeight.w400, height: 1)),
                      Text(widget.dest,
                          style: AppType.body(12,
                              color: AppColors.inkMute, w: FontWeight.w500)),
                      Text("ETA ${h}h ${m.toString().padLeft(2, '0')}m",
                          style: AppType.mono(10.5,
                              color: AppColors.terracotta,
                              w: FontWeight.w600)),
                    ],
                  ),
                ],
              ),
              const SizedBox(height: AppSpacing.x5),
              Row(
                children: [
                  _stat("Altitude", "${_fmt(altitude)} m"),
                  const SizedBox(width: 10),
                  _stat("Speed", "$speed km/h"),
                  const SizedBox(width: 10),
                  _stat("Heading", "342°"),
                ],
              ),
              const SizedBox(height: AppSpacing.x4),
              Row(
                children: [
                  const Icon(Icons.info_outline_rounded,
                      size: 14, color: AppColors.inkMute),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      "Live data · powered by OpenSky Network",
                      style: AppType.body(11,
                          color: AppColors.inkMute, w: FontWeight.w500),
                    ),
                  ),
                ],
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _stat(String label, String v) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 10),
        decoration: BoxDecoration(
          color: AppColors.parchmentSoft,
          borderRadius: BorderRadius.circular(AppRadius.md),
          border: Border.all(color: AppColors.hairline),
