class _ProgressLinePainter extends CustomPainter {
  _ProgressLinePainter({required this.progress});
  final double progress;

  @override
  void paint(Canvas canvas, Size size) {
    final y = size.height / 2;
    final base = Paint()
      ..color = AppColors.hairline
      ..strokeWidth = 1.5;
    canvas.drawLine(Offset(0, y), Offset(size.width, y), base);

    final filled = Paint()
      ..color = AppColors.ink
      ..strokeWidth = 2.4
      ..strokeCap = StrokeCap.round;
    canvas.drawLine(
        Offset(0, y), Offset(size.width * progress, y), filled);

    // plane dot
    final cx = size.width * progress;
    final glow = Paint()
      ..color = AppColors.sun.withValues(alpha: 0.4)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6);
    canvas.drawCircle(Offset(cx, y), 8, glow);
    final dot = Paint()..color = AppColors.sun;
    canvas.drawCircle(Offset(cx, y), 5, dot);
    final dotInner = Paint()..color = AppColors.ink;
    canvas.drawCircle(Offset(cx, y), 2, dotInner);
  }

  @override
  bool shouldRepaint(covariant _ProgressLinePainter old) =>
      old.progress != progress;
}

class _MapPainter extends CustomPainter {
  _MapPainter({required this.progress});
  final double progress;

  @override
  void paint(Canvas canvas, Size size) {
    // Deep ocean gradient
    final bg = Paint()
      ..shader = const LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: [Color(0xFF0A1822), Color(0xFF0E1F2C)],
      ).createShader(Offset.zero & size);
    canvas.drawRect(Offset.zero & size, bg);

    // Latitude grid
    final grid = Paint()
      ..color = const Color(0x14FBBC04)
      ..strokeWidth = 0.6;
    for (var i = 1; i < 8; i++) {
      final y = size.height * i / 8;
      canvas.drawLine(Offset(0, y), Offset(size.width, y), grid);
    }
    for (var i = 1; i < 8; i++) {
      final x = size.width * i / 8;
      canvas.drawLine(Offset(x, 0), Offset(x, size.height), grid);
    }

    // Stylized landmasses
    final land = Paint()..color = const Color(0xFF1B2F3C);
    _algeriaShape(canvas, size, land);
    _francePieceShape(canvas, size, land);

    final coast = Paint()
      ..color = AppColors.sun.withValues(alpha: 0.35)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.0;
    _algeriaShape(canvas, size, coast);
    _francePieceShape(canvas, size, coast);

    // Twinkle stars in the void
    final rand = math.Random(42);
    final star = Paint()..color = AppColors.parchment.withValues(alpha: 0.35);
    for (var i = 0; i < 30; i++) {
      final x = rand.nextDouble() * size.width;
      final y = rand.nextDouble() * size.height * 0.5;
      final r = 0.6 + rand.nextDouble() * 1.4;
      final tw = (math.sin((progress * math.pi * 2) + i) + 1) / 2;
      star.color = AppColors.parchment.withValues(alpha: 0.15 + 0.25 * tw);
      canvas.drawCircle(Offset(x, y), r, star);
    }

    // Route — ALG (bottom) → CDG (top)
    final start = Offset(size.width * 0.32, size.height * 0.78);
    final end = Offset(size.width * 0.62, size.height * 0.22);
    final ctrl = Offset(size.width * 0.85, size.height * 0.45);

    final path = Path()
      ..moveTo(start.dx, start.dy)
      ..quadraticBezierTo(ctrl.dx, ctrl.dy, end.dx, end.dy);

    // dashed traveled path
    final routeDashed = Paint()
      ..color = AppColors.parchment.withValues(alpha: 0.25)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.4;
    _drawDashedPath(canvas, path, routeDashed, dash: 6, gap: 5);

    // solid traveled portion
    final metrics = path.computeMetrics().first;
    final traveledPath =
        metrics.extractPath(0, metrics.length * progress);
    final routeSolid = Paint()
      ..color = AppColors.sun
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.4
      ..strokeCap = StrokeCap.round;
    canvas.drawPath(traveledPath, routeSolid);

    // origin / dest pins
    _drawPin(canvas, start, AppColors.emerald, "ALG");
    _drawPin(canvas, end, AppColors.terracotta, "CDG");

    // moving plane
    final t = metrics.getTangentForOffset(metrics.length * progress);
    if (t != null) {
      final glow = Paint()
        ..color = AppColors.sun.withValues(alpha: 0.5)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 12);
      canvas.drawCircle(t.position, 14, glow);

      canvas.save();
      canvas.translate(t.position.dx, t.position.dy);
      final angle = math.atan2(t.vector.dy, t.vector.dx);
      canvas.rotate(angle);
      _drawPlane(canvas);
      canvas.restore();
    }
  }

  void _drawPin(Canvas c, Offset o, Color color, String label) {
    final outer = Paint()
      ..color = color.withValues(alpha: 0.25)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 10);
    c.drawCircle(o, 18, outer);
    final ring = Paint()..color = color;
    c.drawCircle(o, 7, ring);
    final inner = Paint()..color = AppColors.parchment;
    c.drawCircle(o, 2.6, inner);

    final tp = TextPainter(
      text: TextSpan(
        text: label,
        style: TextStyle(
          color: AppColors.parchment,
          fontSize: 10.5,
          fontWeight: FontWeight.w700,
          fontFamily: 'JetBrainsMono',
          letterSpacing: 1.4,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(c, o.translate(12, -7));
  }

  void _drawPlane(Canvas c) {
    final p = Path()
      ..moveTo(12, 0)
      ..lineTo(-6, -7)
      ..lineTo(-3, 0)
      ..lineTo(-6, 7)
      ..close();
    c.drawPath(p, Paint()..color = AppColors.parchment);
    c.drawPath(
      p,
      Paint()
        ..color = AppColors.ink
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.2,
    );
  }

  void _drawDashedPath(Canvas canvas, Path path, Paint paint,
      {double dash = 6, double gap = 4}) {
    for (final m in path.computeMetrics()) {
      var d = 0.0;
      while (d < m.length) {
        canvas.drawPath(m.extractPath(d, d + dash), paint);
        d += dash + gap;
      }
    }
  }

  void _algeriaShape(Canvas c, Size s, Paint paint) {
    final p = Path()
      ..moveTo(s.width * 0.18, s.height * 0.9)
      ..lineTo(s.width * 0.55, s.height * 0.95)
      ..lineTo(s.width * 0.6, s.height * 0.75)
      ..lineTo(s.width * 0.42, s.height * 0.7)
      ..lineTo(s.width * 0.3, s.height * 0.74)
      ..lineTo(s.width * 0.22, s.height * 0.78)
      ..close();
    c.drawPath(p, paint);
  }

  void _francePieceShape(Canvas c, Size s, Paint paint) {
    final p = Path()
      ..moveTo(s.width * 0.5, s.height * 0.32)
      ..lineTo(s.width * 0.78, s.height * 0.28)
      ..lineTo(s.width * 0.82, s.height * 0.12)
      ..lineTo(s.width * 0.62, s.height * 0.08)
      ..lineTo(s.width * 0.48, s.height * 0.18)
      ..close();
    c.drawPath(p, paint);
  }

  @override
  bool shouldRepaint(covariant _MapPainter old) => true;
}

