209	/// Animated dashed flight path between two cities.
210	class _RoutePainter extends CustomPainter {
211	  _RoutePainter(this.t);
212	  final double t;
213	
214	  @override
215	  void paint(Canvas canvas, Size size) {
216	    final start = Offset(20, size.height * 0.78);
217	    final end = Offset(size.width - 20, size.height * 0.32);
218	    final ctrl1 = Offset(size.width * 0.30, size.height * 0.05);
219	    final ctrl2 = Offset(size.width * 0.70, size.height * 0.85);
220	    final path = Path()
221	      ..moveTo(start.dx, start.dy)
222	      ..cubicTo(ctrl1.dx, ctrl1.dy, ctrl2.dx, ctrl2.dy, end.dx, end.dy);
223	
224	    // dashed path drawing
225	    final dashPaint = Paint()
226	      ..color = AppColors.ink.withValues(alpha: 0.25)
227	      ..style = PaintingStyle.stroke
228	      ..strokeWidth = 1.2;
229	    const dashW = 6.0, gap = 4.0;
230	    final metrics = path.computeMetrics().toList();
231	    for (final m in metrics) {
232	      double dist = 0;
233	      while (dist < m.length) {
234	        final next = math.min(dist + dashW, m.length);
235	        canvas.drawPath(m.extractPath(dist, next), dashPaint);
236	        dist = next + gap;
237	      }
238	    }
239	
240	    // moving glow tracer
241	    for (final m in metrics) {
242	      final tracePos = m.getTangentForOffset(m.length * t);
243	      if (tracePos != null) {
244	        final p = tracePos.position;
245	        // glow halo
246	        canvas.drawCircle(p, 14, Paint()..color = AppColors.terracotta.withValues(alpha: 0.18));
247	        canvas.drawCircle(p, 8, Paint()..color = AppColors.terracotta.withValues(alpha: 0.35));
248	        // plane core
249	        canvas.save();
250	        canvas.translate(p.dx, p.dy);
251	        canvas.rotate(tracePos.angle);
252	        final planePaint = Paint()..color = AppColors.ink;
253	        final plane = Path()
254	          ..moveTo(8, 0)
255	          ..lineTo(-6, -4)
256	          ..lineTo(-3, 0)
257	          ..lineTo(-6, 4)
258	          ..close();
259	        canvas.drawPath(plane, planePaint);
260	        canvas.restore();
261	      }
262	    }
263	
264	    // city dots
265	    final dot = Paint()..color = AppColors.ink;
